DO $move$ DECLARE r record; BEGIN FOR r IN SELECT p.oid,p.proname,pg_get_function_identity_arguments(p.oid) args FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('b2b_phase1_partner_visible','b2b_phase1_order_visible','b2b_phase1_simulation_visible') AND p.prosecdef LOOP EXECUTE format('ALTER FUNCTION public.%I(%s) SET SCHEMA platform_private',r.proname,r.args); END LOOP; END $move$;
CREATE OR REPLACE FUNCTION public.b2b_phase1_partner_visible(p_partner uuid,p_technical boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $f$ SELECT platform_private.b2b_phase1_partner_visible(p_partner,p_technical); $f$;
CREATE OR REPLACE FUNCTION public.b2b_phase1_order_visible(p_order uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $f$ SELECT platform_private.b2b_phase1_order_visible(p_order); $f$;
CREATE OR REPLACE FUNCTION public.b2b_phase1_simulation_visible(p_sim uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $f$ SELECT platform_private.b2b_phase1_simulation_visible(p_sim); $f$;
REVOKE ALL ON FUNCTION public.b2b_phase1_partner_visible(uuid,boolean), public.b2b_phase1_order_visible(uuid), public.b2b_phase1_simulation_visible(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.b2b_phase1_partner_visible(uuid,boolean), public.b2b_phase1_order_visible(uuid), public.b2b_phase1_simulation_visible(uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION platform_private.b2b_phase1_partner_visible(uuid,boolean), platform_private.b2b_phase1_order_visible(uuid), platform_private.b2b_phase1_simulation_visible(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION platform_private.b2b_phase1_partner_visible(uuid,boolean), platform_private.b2b_phase1_order_visible(uuid), platform_private.b2b_phase1_simulation_visible(uuid) TO authenticated,service_role;